java_home=os.getenv('JAVA_HOME','')
javac=str(Path(java_home)/'bin/javac') if java_home else 'javac'
java=str(Path(java_home)/'bin/java') if java_home else 'java'
with tempfile.TemporaryDirectory() as tmp:
 d=Path(tmp)
 for name,text in stubs.items():
  p=d/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 sources=[str(p) for p in d.rglob('*.java')]+[str(root/'app/src/main/java/in/scrollcount/probe'/name) for name in ['HourlySyncPlan.java','HourlyFriendJob.java']]
 subprocess.run([javac,'-d',str(d/'classes'),*sources],check=True)
 subprocess.run([java,'-cp',str(d/'classes'),'in.scrollcount.probe.HourlyJobTest'],check=True)
